package org.apache.commons.lang.time;

import junit.framework.TestCase;
import java.util.Calendar;
import java.util.Date;

public class AgentBRT_Lang_53_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.OCTOBER, 10, 10, 30, 30); // Set time to 10:30:30
        calendar.set(Calendar.MILLISECOND, 0);

        // Use truncate to indirectly test modify with rounding on the minute field
        Date truncatedDate = DateUtils.truncate((Object) calendar, Calendar.MINUTE);

        // Convert back to Calendar to check the result
        calendar.setTime(truncatedDate);

        // Expect the time to be rounded to 10:31:00
        assertEquals(10, calendar.get(Calendar.HOUR_OF_DAY));
        assertEquals(31, calendar.get(Calendar.MINUTE));
        assertEquals(0, calendar.get(Calendar.SECOND));
        assertEquals(0, calendar.get(Calendar.MILLISECOND));
    }
}

