package org.apache.commons.lang.time;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Calendar;

public class AgentBRT_Lang_53_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        Calendar calendar = Calendar.getInstance();
        calendar.set(2023, Calendar.OCTOBER, 10, 10, 29, 30); // Set time to 10:29:30
        calendar.set(Calendar.MILLISECOND, 0);

        // Call modify with rounding on the minute field
        DateUtils.modify(calendar, Calendar.MINUTE, true);

        // Expect the time to be rounded to 10:30:00
        assertEquals(10, calendar.get(Calendar.HOUR_OF_DAY));
        assertEquals(30, calendar.get(Calendar.MINUTE));
        assertEquals(0, calendar.get(Calendar.SECOND));
        assertEquals(0, calendar.get(Calendar.MILLISECOND));
    }
}

